#!/bin/sh
# Install or refresh the MeshMux root core LaunchDaemon (com.meshmux.core).
#
# Run from an administrator-authorized terminal:
#   sudo packaging/macos/install-core-daemon.sh
#   sudo packaging/macos/install-core-daemon.sh /Applications/MeshMux.app/Contents/MacOS/meshmux
#
# The script only prints and executes the plan generated by the installed CLI;
# it does not read or copy the member configuration itself. The protected copy
# under /Library/Application Support/MeshMux/core is written here, once, and is
# the only configuration the running daemon reads.
set -eu

CLI=${1:-/Applications/MeshMux.app/Contents/MacOS/meshmux}

if [ "$(id -u)" -ne 0 ]; then
	echo "需要管理员权限：sudo $0" >&2
	exit 1
fi
if [ ! -x "$CLI" ]; then
	echo "找不到可执行的 MeshMux CLI: $CLI" >&2
	exit 1
fi

PLAN=$("$CLI" core-service plan install)
printf '%s\n' "$PLAN" | /bin/sh
